# A local stand-in for the API: it keeps each request body and answers 400. It listens on 127.0.0.1 only.
use IO::Socket::INET; my ($port,$dir)=@ARGV; my $s=IO::Socket::INET->new(LocalAddr=>'127.0.0.1',LocalPort=>$port,Listen=>16,ReuseAddr=>1) or die; my $n=0;
while (my $c=$s->accept) { my $h=''; while(<$c>){ $h.=$_; last if /^\r?\n$/ } my ($l)=$h=~/content-length: *(\d+)/i; my $b=''; if($l){ my $r=0; while($r<$l){ my $k=read($c,$b,$l-$r,$r); last unless $k; $r+=$k } } $n++; if($h=~/POST .*messages/){ open F,">","$dir/req.$n"; binmode F; print F $b; close F; open G,">","$dir/hdr.$n"; print G $h; close G } my $e='{"type":"error","error":{"type":"invalid_request_error","message":"rehearsal"}}'; print $c "HTTP/1.1 400 Bad Request\r\ncontent-type: application/json\r\ncontent-length: ".length($e)."\r\nconnection: close\r\n\r\n$e"; close $c }
